<script setup lang="ts">
import type { ConnectedMailbox } from '../services/connectedMailboxApi'
const props=defineProps<{workspaceId:string;locale:'es'|'en';demo?:boolean}>()
const api=useConnectedMailbox(),route=useRoute(),es=computed(()=>props.locale==='es')
const callbackNotice=ref(''),connectConsent=ref(false)
const hasConnected=computed(()=>connections.value.some(c=>c.status==='connected'))
function detectionState(c:ConnectedMailbox){return c.background?.state||(c.status==='reconnect_required'?'reconnect_required':!backgroundAvailable.value?'unavailable':c.background?.enabled?'starting':'inactive')}
function detectionTone(c:ConnectedMailbox){const state=detectionState(c);return state==='active'?'success':['paused','reconnect_required'].includes(state)?'warning':'info'}
function detectionTitle(c:ConnectedMailbox){if(c.background?.retrying&&!c.background?.failed)return es.value?'Análisis en espera':'Analysis waiting';const state=detectionState(c);return es.value?({active:'Detección activa',starting:'Preparando la detección',inactive:'Activa la detección',unavailable:'Detección en preparación',paused:'La detección está interrumpida',reconnect_required:'Reconecta Gmail'}[state]||'Comprobando detección'):({active:'Detection active',starting:'Starting detection',inactive:'Enable detection',unavailable:'Detection in preparation',paused:'Detection is interrupted',reconnect_required:'Reconnect Gmail'}[state]||'Checking detection')}
const aiConfigured=ref<boolean|null>(null)
const backgroundAvailable=ref(false),backgroundProcessor=ref(''),backgroundConsents=ref<string[]>([])
const transport=ref('nylas')
const loading=ref(false),busy=ref(false),configured=ref(false),error=ref(''),connections=ref<ConnectedMailbox[]>([]),email=ref(''),provider=ref('auto'),disconnectId=ref('')
const available=ref(true),waitlisted=ref(false),chooseProvider=ref(false)
const approvalRequired=ref(true),accessStatus=ref('not_requested'),requestedEmail=ref('')
const canConnect=computed(()=>!approvalRequired.value||accessStatus.value==='approved')
let generation=0
const callbackMessage=computed(()=>{
 if(callbackNotice.value)return callbackNotice.value
 const state=String(route.query.mailbox||'')
 if(state==='authorize')return ''
 if(state==='connected')return es.value?'Correo conectado.':'Email connected.'
 if(state==='cancelled')return es.value?'Has cancelado la autorización.':'Authorization cancelled.'
 if(state==='account_mismatch')return es.value?'La cuenta autorizada no coincide con el correo indicado.':'The authorized account does not match the address entered.'
 if(state)return es.value?'No se completó la conexión. Vuelve a autorizar el correo.':'Connection was not completed. Authorize your email again.'
 return ''
})
async function joinWaitlist(){if(busy.value||loading.value||props.demo)return;const turn=generation;busy.value=true;error.value='';try{const result=await api.waitlist(props.workspaceId,email.value.trim().toLowerCase(),props.locale);if(turn===generation){waitlisted.value=result.waitlisted;accessStatus.value=result.status;requestedEmail.value=result.requestedEmail}}catch(e){if(turn===generation)error.value=message(e)}finally{if(turn===generation)busy.value=false}}
function message(e:unknown){const code=e instanceof Error?e.message:'';if(code==='verified_email_required')return es.value?'Verifica el correo de tu cuenta antes de solicitar acceso.':'Verify your account email before requesting access.';if(code==='beta_request_email_locked')return es.value?'Tu solicitud ya tiene un correo asignado. Contacta con Cuebooker para cambiarlo.':'Your request already has an email address. Contact Cuebooker to change it.';if(['mailbox_beta_approval_required','mailbox_beta_email_not_approved'].includes(code)){return es.value?'Necesitas aprobación para conectar este correo. Vuelve a comprobar el estado.':'Approval is required to connect this email. Check the status again.';}if(['mailbox_request_timeout','mailbox_storage_timeout','mailbox_provider_timeout'].includes(code))return es.value?'La comprobación ha tardado demasiado. Vuelve a comprobar el estado.':'The check took too long. Check the status again.';if(code==='mailbox_provider_selection_required'){chooseProvider.value=true;provider.value='';return es.value?'Elige dónde consultas este correo para continuar.':'Choose where you access this email to continue.'}if(code==='mailbox_beta_full'){available.value=false;return es.value?'Las plazas están completas. Puedes apuntarte a la lista de espera.':'Beta places are full. You can join the waiting list.'}return es.value?(code==='mailbox_not_configured'?'Estamos preparando la conexión de correo.':code==='workspace_access_denied'?'Tu rol no permite conectar correo.':code==='mailbox_attempt_limit'?'Hay demasiados intentos pendientes. Espera diez minutos.':'No se pudo completar la operación. Inténtalo de nuevo.'):'The operation could not be completed. Please retry.'}
async function load(){
 const turn=++generation,workspace=props.workspaceId;
 loading.value=true;busy.value=false;connectConsent.value=false;aiConfigured.value=null;backgroundAvailable.value=false;backgroundProcessor.value='';backgroundConsents.value=[];
 error.value='';connections.value=[];configured.value=false;disconnectId.value='';available.value=true;waitlisted.value=false;chooseProvider.value=false;provider.value='auto';email.value='';approvalRequired.value=true;accessStatus.value='not_requested';requestedEmail.value='';
 try{if(!props.demo){
  if(import.meta.client){const params=new URLSearchParams(window.location.hash.slice(1)),code=params.get('mailbox_code'),state=params.get('mailbox_state');if(code&&state){window.history.replaceState(window.history.state,'',window.location.pathname+window.location.search);const completed=await api.complete(workspace,state,code);callbackNotice.value=completed.detectionPending?(es.value?'Correo conectado. No se ha podido iniciar la detección; consulta su estado debajo.':'Email connected. Detection could not start; check its status below.'):(es.value?'Correo conectado.':'Email connected.')}}
  const result=await api.status(workspace);
  if(turn===generation){transport.value=result.transport||'nylas';configured.value=result.configured;aiConfigured.value=result.ai?.configured??null;backgroundAvailable.value=result.background?.available===true;backgroundProcessor.value=result.background?.processor||'';connections.value=result.connections;available.value=result.beta.available;waitlisted.value=result.beta.waitlisted;approvalRequired.value=result.beta.approvalRequired!==false;accessStatus.value=result.beta.status||'not_requested';requestedEmail.value=result.beta.requestedEmail||'';if(approvalRequired.value)email.value=requestedEmail.value}
 }}catch(e){if(turn===generation)error.value=message(e)}finally{if(turn===generation)loading.value=false}
}
async function connect(){if(busy.value||loading.value||props.demo||!canConnect.value||(transport.value==='gmail'&&backgroundAvailable.value&&!connectConsent.value))return;busy.value=true;error.value='';const workspace=props.workspaceId;try{const result=await api.connect(workspace,email.value,provider.value,transport.value==='gmail'&&backgroundAvailable.value&&connectConsent.value?backgroundProcessor.value:undefined);if(workspace!==props.workspaceId)return;const target=new URL(result.authorizationUrl);if(!((['https://api.us.nylas.com','https://api.eu.nylas.com'].includes(target.origin)&&target.pathname==='/v3/connect/auth')||(target.origin==='https://accounts.google.com'&&target.pathname==='/o/oauth2/v2/auth')))throw new Error('invalid_redirect');window.location.assign(target.href)}catch(e){error.value=message(e)}finally{busy.value=false}}
async function disconnect(id:string){busy.value=true;error.value='';try{await api.disconnect(props.workspaceId,id);await load()}catch(e){error.value=message(e)}finally{busy.value=false}}
async function pauseBackground(id:string){if(busy.value||props.demo)return;const turn=generation,workspace=props.workspaceId;busy.value=true;error.value='';try{await api.pauseBackground(workspace,id);if(turn===generation)await load()}catch(e){if(turn===generation)error.value=message(e)}finally{busy.value=false}}
async function authorizeBackground(id:string){if(busy.value||props.demo||!backgroundAvailable.value||!backgroundConsents.value.includes(id))return;const turn=generation,workspace=props.workspaceId;busy.value=true;error.value='';try{await api.authorizeBackground(workspace,id,backgroundProcessor.value);if(turn===generation)await load()}catch(e){if(turn===generation)error.value=message(e)}finally{busy.value=false}}
watch(()=>[props.workspaceId,props.demo],load,{immediate:true})
onBeforeUnmount(()=>{generation++})
function statusName(status:string){return es.value?(status==='connected'?'Conectado':status==='reconnect_required'?'Requiere autorización':'No se pudo verificar'):(status==='connected'?'Connected':status==='reconnect_required'?'Authorization required':'Could not verify')}
</script>
<template>
<section class="mailbox-panel" aria-labelledby="mailbox-heading" :aria-busy="loading||busy">
 <header><div><p class="mailbox-panel__eyebrow">{{es?'SOLICITUDES POR CORREO':'EMAIL ENQUIRIES'}}</p><h2 id="mailbox-heading">{{es?'Tu correo en Cuebooker':'Your email in Cuebooker'}}</h2></div></header>
 <p v-if="!hasConnected">{{es?'Conecta Gmail para reunir aquí las solicitudes que recibes por correo.':'Connect Gmail to collect incoming enquiries here.'}}</p>
 <MailboxStatusNotice v-if="!hasConnected" tone="info" :title="es?'Tú controlas la conexión':'You control the connection'"><p>{{es?'Google autoriza a Cuebooker a leer mensajes y enviar las respuestas que tú decidas. No recibimos tu contraseña ni respondemos automáticamente.':'Google authorizes Cuebooker to read messages and send the replies you choose. We do not receive your password or reply automatically.'}}</p></MailboxStatusNotice>
 <details class="mailbox-panel__ai mailbox-panel__details"><summary>{{es?'Cómo usamos tu correo':'How we use your email'}}</summary>
  <p>{{es?'Con tu autorización, analizamos los mensajes nuevos de la bandeja de entrada para detectar peticiones de actuación. Groq recibe el asunto y hasta 2.500 caracteres del mensaje. No descargamos adjuntos para este análisis.':'With your permission, we analyze new inbox messages to detect performance enquiries. Groq receives the subject and up to 2,500 characters of the message. We do not download attachments for this analysis.'}}</p>
  <p>{{es?'El permiso de Google permite leer el buzón; nuestra detección se limita a mensajes nuevos desde su activación. Revisar correos anteriores es una opción aparte.':'The Google permission allows mailbox reading; detection is limited to new messages from activation. Reviewing earlier messages is a separate option.'}}</p>
  <p>{{es?'Las solicitudes y sus conversaciones se guardan en tu workspace y las pueden ver sus miembros autorizados. Desconectar detiene el acceso y elimina los tokens locales; las solicitudes guardadas se conservan.':'Enquiries and their conversations are saved in your workspace and visible to authorized members. Disconnecting stops access and removes local tokens; saved enquiries are retained.'}}</p>
  <NuxtLink to="/privacidad">{{es?'Leer la política de privacidad':'Read the privacy policy'}}</NuxtLink>
 </details>
 <details class="mailbox-panel__details"><summary>{{es?'Condiciones de la beta':'Beta conditions'}}</summary><MailboxBetaNotice :locale="locale" /><p>{{es?'Durante las pruebas, Google muestra un aviso de aplicación no verificada y pide reconectar cada siete días.':'During testing, Google shows an unverified-app notice and requires reconnection every seven days.'}}</p></details>
 <MailboxStatusNotice v-if="callbackMessage" tone="info"><p>{{callbackMessage}}</p></MailboxStatusNotice>
 <p v-if="loading" role="status">{{es?'Comprobando conexión…':'Checking connection…'}}</p>
 <MailboxStatusNotice v-else-if="!configured&&!error" tone="info"><p>{{demo?(es?'Vista de prueba. No conecta buzones reales.':'Preview. It does not connect real mailboxes.'):(es?'Estamos preparando la conexión de correo.':'We are preparing email connection.')}}</p></MailboxStatusNotice>
 <article v-for="connection in connections" :key="connection.id" class="mailbox-panel__connection">
  <div><strong>{{connection.email}}</strong><small>{{connection.provider==='google'?'Gmail':connection.provider==='microsoft'?'Outlook / Hotmail':'IMAP'}} · {{statusName(connection.status)}}</small></div>
  <button type="button" :disabled="busy" @click="disconnectId=connection.id">{{es?'Desconectar':'Disconnect'}}</button>
  <div class="mailbox-panel__detection">
   <MailboxStatusNotice :tone="detectionTone(connection)" :title="detectionTitle(connection)">
    <p v-if="detectionState(connection)==='active'">{{es?'Revisamos los mensajes nuevos. Si detectamos una petición de actuación, aparecerá en Solicitudes. Tú decides cómo responder.':'We check new messages. Performance enquiries appear in Enquiries. You decide how to reply.'}}</p>
    <p v-else-if="detectionState(connection)==='unavailable'">{{es?'Tu correo está conectado. La detección automática todavía no está disponible en esta beta.':'Your email is connected. Automatic detection is not available in this beta yet.'}}</p>
    <p v-else-if="detectionState(connection)==='starting'">{{es?'Estamos iniciando el seguimiento. Todavía no hemos confirmado que la detección esté activa.':'We are starting monitoring. Active detection has not been confirmed yet.'}}</p>
    <p v-else-if="detectionState(connection)==='reconnect_required'">{{es?'La autorización ha caducado. Conecta de nuevo este correo para continuar.':'Authorization has expired. Reconnect this email to continue.'}}</p>
    <p v-else-if="connection.background?.retrying&&!connection.background?.failed">{{es?'La IA ha alcanzado un límite temporal. Conservamos los mensajes pendientes y continuaremos automáticamente.':'AI has reached a temporary limit. Pending messages remain saved and processing will resume automatically.'}}</p>
    <p v-else-if="detectionState(connection)==='paused'">{{es?'No podemos confirmar que todos los mensajes se estén procesando. Los pendientes siguen guardados.':'We cannot confirm that all messages are being processed. Pending messages remain saved.'}}</p>
    <p v-else>{{es?'Actívala una vez para revisar los mensajes nuevos sin tener que abrir Cuebooker.':'Enable it once to check new messages without opening Cuebooker.'}}</p>
   </MailboxStatusNotice>
   <MailboxStatusNotice v-if="connection.background?.failed && detectionState(connection)==='active'" tone="warning" :title="es?'Mensajes pendientes de revisión':'Messages requiring review'"><p>{{connection.background.failed}} {{es?'mensajes recientes no pudieron analizarse. Gmail sigue conectado.':'recent messages could not be analyzed. Gmail remains connected.'}}</p></MailboxStatusNotice>
   <template v-if="connection.background?.enabled"><button type="button" :disabled="busy||demo" @click="pauseBackground(connection.id)">{{es?'Pausar detección':'Pause detection'}}</button></template>
   <template v-else-if="backgroundAvailable&&connection.status==='connected'"><label class="mailbox-panel__consent"><input v-model="backgroundConsents" type="checkbox" :value="connection.id" :disabled="busy||demo"><span>{{es?'Autorizo analizar con Groq los mensajes nuevos para detectar solicitudes.':'I authorize Groq analysis of new messages to detect enquiries.'}}</span></label><button type="button" :disabled="busy||demo||!backgroundConsents.includes(connection.id)" @click="authorizeBackground(connection.id)">{{es?'Activar detección':'Enable detection'}}</button></template>
  </div>
  <div v-if="disconnectId===connection.id" class="mailbox-panel__confirm"><p>{{es?'Dejaremos de acceder al buzón. Las solicitudes guardadas se conservan.':'We will stop accessing the mailbox. Saved enquiries are retained.'}}</p><button type="button" :disabled="busy" @click="disconnect(connection.id)">{{es?'Desconectar correo':'Disconnect email'}}</button><button type="button" :disabled="busy" @click="disconnectId=''">{{es?'Cancelar':'Cancel'}}</button></div>
 </article>
 <section v-if="!demo&&!loading&&approvalRequired&&!error&&!hasConnected" class="mailbox-panel__access" aria-labelledby="mailbox-beta-access-heading">
  <h3 v-if="accessStatus!=='approved'" id="mailbox-beta-access-heading">{{es?'Prueba la conexión de correo':'Try email connection'}}</h3>
  <MailboxStatusNotice v-if="accessStatus==='pending'" tone="info"><strong>{{es?'Solicitud recibida':'Request received'}}</strong><p>{{es?'Te avisaremos en el correo verificado de tu cuenta de Cuebooker cuando aprobemos el acceso. Después vuelve aquí para conectar Gmail.':'We will email your verified Cuebooker account address when access is approved. Then return here to connect Gmail.'}}</p></MailboxStatusNotice>
  <MailboxStatusNotice v-else-if="accessStatus==='rejected'" tone="warning"><p>{{es?'No hemos aprobado tu acceso por ahora. Puedes seguir usando Cuebooker.':'Access has not been approved at this time. You can keep using Cuebooker.'}}</p></MailboxStatusNotice>
  <form v-else-if="accessStatus!=='approved'" @submit.prevent="joinWaitlist"><label><span>{{es?'Tu cuenta de Google':'Your Google account'}}</span><input v-model="email" type="email" autocomplete="email" maxlength="254" required :disabled="busy"></label><p>{{es?'Solicitar acceso no permite leer tu correo.':'Requesting access does not grant email access.'}}</p><button type="submit" :disabled="busy">{{busy?(es?'Guardando…':'Saving…'):(es?'Solicitar acceso':'Request access')}}</button></form>
 </section>
 <MailboxStatusNotice v-if="!demo&&!loading&&!hasConnected&&accessStatus==='approved'" tone="success"><strong>{{es?'Acceso aprobado':'Access approved'}}</strong><p>{{es?'Ya puedes conectar la cuenta de Google que solicitaste.':'You can now connect the Google account you requested.'}}</p></MailboxStatusNotice>
 <MailboxStatusNotice v-if="!demo&&!loading&&!hasConnected&&!available" tone="warning"><strong>{{es?'Plazas de correo completas':'Email places are full'}}</strong><p>{{es?'Por ahora no podemos conectar otro buzón. Puedes solicitar acceso y seguir usando Cuebooker mientras esperas.':'We cannot connect another mailbox right now. You can request access and keep using Cuebooker while you wait.'}}</p></MailboxStatusNotice>
 <form v-if="canConnect&&!hasConnected&&(available||connections.length)" @submit.prevent="connect"><fieldset :disabled="busy||loading||!configured">
  <label><span>{{es?'Correo que quieres conectar':'Email to connect'}}</span><input v-model="email" type="email" autocomplete="email" maxlength="254" required :readonly="approvalRequired" placeholder="booking@tu-dominio.com"></label>
  <label v-if="chooseProvider"><span>{{es?'Servicio de correo':'Email service'}}</span><select v-model="provider" required><option value="" disabled>{{es?'Selecciona tu servicio':'Select your service'}}</option><option value="google">Gmail / Google Workspace</option><option value="microsoft">Outlook / Hotmail / Microsoft 365</option><option value="imap">{{es?'Otro servicio':'Another service'}}</option></select></label>
  <label v-if="backgroundAvailable&&transport==='gmail'" class="mailbox-panel__consent"><input v-model="connectConsent" type="checkbox"><span>{{es?'Autorizo a Cuebooker a analizar con Groq los mensajes nuevos para detectar solicitudes.':'I authorize Cuebooker to analyze new messages with Groq to detect enquiries.'}}</span></label>
  <MailboxStatusNotice v-else tone="info"><p>{{es?'Puedes conectar Gmail. La detección automática aún está en preparación.':'You can connect Gmail. Automatic detection is still in preparation.'}}</p></MailboxStatusNotice>
  <button class="mailbox-panel__connect" type="submit" :disabled="(transport==='gmail'&&backgroundAvailable&&!connectConsent)||(!available&&!connections.some(c=>c.email===email.trim().toLowerCase()))">{{busy?(es?'Conectando…':'Connecting…'):(transport==='gmail'?(es?'Conectar Gmail':'Connect Gmail'):(es?'Conectar correo':'Connect email'))}}</button>
 </fieldset></form>
 <MailboxStatusNotice v-if="error" tone="error"><p>{{error}}</p></MailboxStatusNotice><button v-if="error" type="button" :disabled="busy||loading" @click="load">{{es?'Volver a comprobar':'Check again'}}</button>
</section>
</template>
<style scoped>
.mailbox-panel__detection{flex-basis:100%;font-size:12px}.mailbox-panel__detection summary{cursor:pointer}.mailbox-panel__detection summary:focus-visible{outline:2px solid var(--cue-toggle);outline-offset:3px}
.mailbox-panel .mailbox-panel__consent{display:flex;align-items:start;gap:9px;margin:14px 0}.mailbox-panel .mailbox-panel__consent input{width:18px;min-height:18px;height:18px;padding:0;flex-shrink:0;accent-color:var(--cue-toggle)}
.mailbox-panel{margin:28px 0;padding:24px;border:1px solid var(--cue-border);border-radius:var(--cue-radius-panel);background:var(--cue-surface);color:var(--cue-text)}.mailbox-panel header{display:flex;justify-content:space-between;align-items:start;gap:16px}.mailbox-panel h2{font-size:20px;margin:6px 0 16px}.mailbox-panel p{font-size:13px;line-height:1.6;color:var(--cue-muted)}.mailbox-panel__eyebrow{font:10px monospace;letter-spacing:.12em;margin:0}.mailbox-panel__badge{font:11px monospace;white-space:nowrap;padding:7px 10px;border:1px solid var(--cue-border);border-radius:var(--cue-radius-control);color:var(--cue-muted)}.mailbox-panel fieldset{border:0;padding:0;margin:20px 0 0;min-width:0}.mailbox-panel form{max-width:560px}.mailbox-panel label{display:grid;gap:8px;min-width:0;font-size:12px}.mailbox-panel input,.mailbox-panel select,.mailbox-panel button{box-sizing:border-box;min-height:44px;border:1px solid var(--cue-border);border-radius:var(--cue-radius-control);background:var(--cue-bg);color:var(--cue-text);font:inherit;font-size:12px;padding:10px 12px}.mailbox-panel input,.mailbox-panel select{width:100%;min-width:0}.mailbox-panel button{cursor:pointer}.mailbox-panel__ai{margin-top:14px}.mailbox-panel__ai summary{cursor:pointer;font-size:12px}.mailbox-panel__ai summary:focus-visible{outline:2px solid var(--cue-toggle);outline-offset:3px}.mailbox-panel :disabled{opacity:.5;cursor:default}.mailbox-panel input:focus-visible,.mailbox-panel select:focus-visible,.mailbox-panel button:focus-visible{outline:2px solid var(--cue-toggle);outline-offset:3px}.mailbox-panel .mailbox-panel__connect{background:var(--cue-accent);color:#080808;font-weight:700}.mailbox-panel__notice{border-left:3px solid #679cdc;background:color-mix(in srgb,#679cdc 9%,var(--cue-bg));padding:12px 16px;border-radius:var(--cue-radius-control)}.mailbox-panel__error{border-left:3px solid #e65e6a;background:color-mix(in srgb,#e65e6a 9%,var(--cue-bg));padding:12px 16px;border-radius:var(--cue-radius-control)}.mailbox-panel__connection{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:14px;border-top:1px solid var(--cue-border);padding:16px 0}.mailbox-panel__connection strong{overflow-wrap:anywhere;font-size:13px}.mailbox-panel__connection small{display:block;color:var(--cue-muted);font-size:11px;margin-top:6px}.mailbox-panel__confirm{width:100%}.mailbox-panel__confirm button{margin:0 8px 8px 0}@media(max-width:600px){.mailbox-panel{padding:18px 14px}.mailbox-panel header{flex-direction:column;gap:0}.mailbox-panel__fields{grid-template-columns:1fr}.mailbox-panel h2{margin-bottom:12px}.mailbox-panel__badge{margin-bottom:10px}}
</style>

<style scoped>
.mailbox-panel__details{margin:12px 0}.mailbox-panel__details summary{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:44px;padding:10px 12px;border:1px solid var(--cue-border);border-radius:var(--cue-radius-control);background:var(--cue-raised);font-size:13px;color:var(--cue-text);cursor:pointer;list-style:none}.mailbox-panel__details summary::-webkit-details-marker{display:none}.mailbox-panel__details summary::after{content:'';width:8px;height:8px;border-right:2px solid currentColor;border-bottom:2px solid currentColor;transform:rotate(45deg);transition:transform .15s;flex-shrink:0}.mailbox-panel__details[open] summary::after{transform:rotate(225deg)}.mailbox-panel__details summary:focus-visible{outline:2px solid var(--cue-toggle);outline-offset:3px}.mailbox-panel__detection{width:100%}
</style>
